command:
$ErrorActionPreference='Stop'
$repo=[Environment]::GetEnvironmentVariable('DCOIR_REPO_ROOT','Machine')
if([string]::IsNullOrWhiteSpace($repo)){$repo=$env:GITHUB_WORKSPACE}
$branch='test-494-dcoir-production-acceptance-post497'
$ref=('refs/heads/'+$branch)
$remote=(git -C $repo ls-remote --heads origin $ref)
if([string]::IsNullOrWhiteSpace(($remote -join ''))){Write-Host 'BRANCH_ALREADY_ABSENT=true'; exit 0}
$api='https://api.github.com/repos/malwaredevil/dcoir-collector/pulls?state=open&head=malwaredevil:'+[uri]::EscapeDataString($branch)+'&per_page=10'
$headers=@{'Authorization'=('Bearer '+$env:GITHUB_TOKEN);'Accept'='application/vnd.github+json';'X-GitHub-Api-Version'='2022-11-28'}
$prs=Invoke-RestMethod -Uri $api -Headers $headers -Method Get
if(@($prs).Count -ne 0){throw ('Open PR still references '+$branch)}
git -C $repo push origin --delete $branch
if($LASTEXITCODE -ne 0){throw 'branch deletion failed'}
$remaining=(git -C $repo ls-remote --heads origin $ref)
if(-not [string]::IsNullOrWhiteSpace(($remaining -join ''))){throw 'branch still exists after deletion'}
Write-Host 'BRANCH_DELETED=true'
